extends RefCounted

var texture: Texture2D
var grid: SheetGrid


func _init(
	p_texture: Texture2D,
	p_card_size: Vector2,
	p_margin: Vector2 = Vector2.ZERO,
	p_spacing: Vector2 = Vector2.ZERO
) -> void:
	texture = p_texture
	grid = SheetGrid.new(p_card_size, p_margin, p_spacing)


func get_card_region(column: int, row: int) -> Rect2:
	return grid.get_cell_rect(column, row)


func get_card_texture(column: int, row: int) -> AtlasTexture:
	return grid.create_atlas_texture(texture, column, row)


func get_reward_card(score: int) -> AtlasTexture:
	if score >= 2:
		return get_card_texture(3, 0)
	elif score == 1:
		return get_card_texture(2, 0)
	else:
		return get_card_texture(1, 0)
